export interface ConnectorConfig {
  githubToken: string
  githubOwner: string
  githubRepo: string
  zendeskSubdomain: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  detail: {
    subject: string
    description: string
    id: string
  }
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  githubCommentId: number
  githubCommentUrl: string
}

async function githubRequest(
  config: ConnectorConfig,
  url: string,
  method: string,
  body: unknown,
): Promise<Response> {
  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn(url, {
    method,
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'User-Agent': 'patchbay-connector',
    },
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`GitHub API error: ${response.status} ${response.statusText} for ${method} ${url}`)
  }
  return response
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id')
  }

  const issueUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const issueResponse = await githubRequest(config, issueUrl, 'POST', {
    title: payload.detail.subject,
    body: payload.detail.description,
  })
  const issueData = (await issueResponse.json()) as { number: number; html_url: string }

  const commentUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues/${issueData.number}/comments`
  const zendeskTicketUrl = `https://${config.zendeskSubdomain}.zendesk.com/agent/tickets/${payload.detail.id}`
  const commentResponse = await githubRequest(config, commentUrl, 'POST', {
    body: `Corresponding Zendesk ticket created: ${zendeskTicketUrl}`,
  })
  const commentData = (await commentResponse.json()) as { id: number; html_url: string }

  return {
    githubIssueNumber: issueData.number,
    githubIssueUrl: issueData.html_url,
    githubCommentId: commentData.id,
    githubCommentUrl: commentData.html_url,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubToken: 'test-token',
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      zendeskSubdomain: 'yoursubdomain',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubCommentId).toBe(1)
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const f = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/Hello-World/issues' && req.method === 'POST') {
        return jsonResponse({ id: 1347, number: 1347, html_url: 'https://github.com/octocat/Hello-World/issues/1347' }, 201)
      }
      if (req.url === 'https://api.github.com/repos/octocat/Hello-World/issues/1347/comments' && req.method === 'POST') {
        return jsonResponse({ id: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1347#issuecomment-1234567' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = f.fetch
    calls = f.calls
    baseConfig = {
      githubToken: 'test-token',
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      zendeskSubdomain: 'yoursubdomain',
      fetch,
    }
  })

  it('creates issue and posts comment on happy path', async () => {
    const payload: ZendeskTicketCreatedPayload = {
      detail: {
        subject: 'Test ticket',
        description: 'Test description',
        id: '12345',
      },
    }
    const result = await handle(payload, baseConfig)

    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/1347')
    expect(result.githubCommentId).toBe(1)
    expect(result.githubCommentUrl).toBe('https://github.com/octocat/Hello-World/issues/1347#issuecomment-1234567')

    expect(calls).toHaveLength(2)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.github.com/repos/octocat/Hello-World/issues')
    expect(calls[0].json).toEqual({ title: 'Test ticket', body: 'Test description' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-token')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://api.github.com/repos/octocat/Hello-World/issues/1347/comments')
    expect(calls[1].json).toEqual({ body: 'Corresponding Zendesk ticket created: https://yoursubdomain.zendesk.com/agent/tickets/12345' })
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-token')
  })

  it('throws when detail.subject is missing', async () => {
    const payload = { detail: { description: 'desc', id: '1' } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.subject')
    expect(calls).toHaveLength(0)
  })

  it('throws when detail.description is missing', async () => {
    const payload = { detail: { subject: 'subj', id: '1' } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.description')
    expect(calls).toHaveLength(0)
  })

  it('throws when detail.id is missing', async () => {
    const payload = { detail: { subject: 'subj', description: 'desc' } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.id')
    expect(calls).toHaveLength(0)
  })

  it('throws on non-2xx response from issue creation', async () => {
    const f = fakeFetch((req) => jsonResponse({ error: 'bad' }, 401))
    const config = { ...baseConfig, fetch: f.fetch }
    const payload: ZendeskTicketCreatedPayload = { detail: { subject: 's', description: 'd', id: '1' } }
    await expect(handle(payload, config)).rejects.toThrow('GitHub API error: 401 Unauthorized for POST https://api.github.com/repos/octocat/Hello-World/issues')
    expect(f.calls).toHaveLength(1)
  })

  it('throws on non-2xx response from comment creation', async () => {
    const f = fakeFetch((req) => {
      if (req.url.endsWith('/issues')) return jsonResponse({ id: 1, number: 1, html_url: 'u' }, 201)
      return jsonResponse({ error: 'forbidden' }, 403)
    })
    const config = { ...baseConfig, fetch: f.fetch }
    const payload: ZendeskTicketCreatedPayload = { detail: { subject: 's', description: 'd', id: '1' } }
    await expect(handle(payload, config)).rejects.toThrow('GitHub API error: 403 Forbidden for POST https://api.github.com/repos/octocat/Hello-World/issues/1/comments')
    expect(f.calls).toHaveLength(2)
  })

  it('uses injected fetch over global fetch', async () => {
    const f = fakeFetch((req) => {
      if (req.url.endsWith('/issues')) return jsonResponse({ id: 2, number: 2, html_url: 'u2' }, 201)
      return jsonResponse({ id: 2, html_url: 'c2' }, 201)
    })
    const config = { ...baseConfig, fetch: f.fetch }
    const payload: ZendeskTicketCreatedPayload = { detail: { subject: 's', description: 'd', id: '1' } }
    await handle(payload, config)
    expect(f.calls).toHaveLength(2)
  })
})

